/** A version: a struct and a nested table among fixed fields, written whole */
export class Box {
    /**
     * The version of the format, which the header carries and the
     * constructor checks
     */
    static readonly FORMAT_VERSION = 1;

    static readonly #LAYOUT = TableLayout.create({ versioned: true });

    readonly #buffer: ByteBuffer;

    /** @throws {DecodeError} If `bytes` are in another format version. */
    constructor(bytes: Uint8Array) {
        this.#buffer = new ByteBuffer(bytes, Box.#LAYOUT);

        const version = this.#buffer.getVersion();
        if (version !== Box.FORMAT_VERSION) {
            throw new DecodeError(
                `Expected format version ${Box.FORMAT_VERSION} of Box, got ${version}`
            );
        }
    }

    /**
     * Returns the format version in the header of `bytes`, without checking
     * it, so that an application can choose the reader of that version
     *
     * @throws {DecodeError} If the header doesn't fit in `bytes`.
     */
    static versionOf(bytes: Uint8Array): number {
        return new ByteBuffer(bytes, Box.#LAYOUT).getVersion();
    }

    /** Writes a `Box` with every field */
    static serialize(fields: BoxFields): Uint8Array {
        const sizer = new TableSizer(3, Box.#LAYOUT, Box.FORMAT_VERSION);
        sizer.addStruct(Vec2.SIZE);
        sizer.addStruct(Vec2.SIZE);
        sizer.addTable(Range.ALIGNMENT);
        Range.size(sizer, fields.range);

        const writer = sizer.writer();
        writer.setStruct(0, Vec2.serialize(fields.min));
        writer.setStruct(1, Vec2.serialize(fields.max));
        writer.setTable(2, Range.ALIGNMENT);
        Range.write(writer, fields.range);

        return writer.bytes();
    }

    /**
     * Writes a `Box` with every field into the start of `bytes`,
     * rather than into new bytes, and returns the view of them that holds
     * it. The view, and what's read from it, change when the bytes are
     * written again. Reusing bytes saves allocating and zeroing new ones,
     * which takes longest for large tables.
     *
     * @throws {RangeError} If `bytes` are shorter than the table, before
     * any of them is written.
     */
    static serializeInto(fields: BoxFields, bytes: Uint8Array): Uint8Array {
        const sizer = new TableSizer(3, Box.#LAYOUT, Box.FORMAT_VERSION);
        sizer.addStruct(Vec2.SIZE);
        sizer.addStruct(Vec2.SIZE);
        sizer.addTable(Range.ALIGNMENT);
        Range.size(sizer, fields.range);

        const writer = sizer.writer(bytes);
        writer.setStruct(0, Vec2.serialize(fields.min));
        writer.setStruct(1, Vec2.serialize(fields.max));
        writer.setTable(2, Range.ALIGNMENT);
        Range.write(writer, fields.range);

        return writer.bytes();
    }

    min(): Vec2 {
        return new Vec2(this.#buffer.bytes(), this.#buffer.rootOffset(0));
    }

    max(): Vec2 {
        return new Vec2(this.#buffer.bytes(), this.#buffer.rootOffset(1));
    }

    range(): Range {
        return new Range(this.#buffer, this.#buffer.rootOffset(2));
    }

    /**
     * Reads every field into the `BoxFields` that writes it, nested
     * tables and the items of vectors and arrays of structs included
     */
    fields(): BoxFields {
        return {
            min: Vec2.read(this.#buffer.bytes(), this.#buffer.rootOffset(0)),
            max: Vec2.read(this.#buffer.bytes(), this.#buffer.rootOffset(1)),
            range: Range.read(this.#buffer, this.#buffer.rootOffset(2))
        };
    }
}

/** The fields of a `Box`, to write */
export interface BoxFields {
    min: Vec2Fields;
    max: Vec2Fields;
    range: RangeFields;
}

/**
 * Fixed fields with a struct and a nested table together, and then other
 * fields
 */
export class Track {
    static readonly #LAYOUT = TableLayout.DEFAULT;

    readonly #buffer: ByteBuffer;

    constructor(bytes: Uint8Array) {
        this.#buffer = new ByteBuffer(bytes, Track.#LAYOUT);
    }

    /** Writes a `Track` with every field */
    static serialize(fields: TrackFields): Uint8Array {
        const sizer = new TableSizer(5, Track.#LAYOUT);
        sizer.addUint32();
        sizer.addStruct(Vec2.SIZE);
        sizer.addTable(Frame.ALIGNMENT);
        Frame.size(sizer, fields.frame);
        sizer.addFloat32Array(fields.points.length);
        sizer.addString(fields.name);

        const writer = sizer.writer();
        writer.setUint32(0, fields.id);
        writer.setStruct(1, Vec2.serialize(fields.origin));
        writer.setTable(2, Frame.ALIGNMENT);
        Frame.write(writer, fields.frame);
        writer.setFloat32Array(3, fields.points);
        writer.setString(4, fields.name);

        return writer.bytes();
    }

    /**
     * Writes a `Track` with every field into the start of `bytes`,
     * rather than into new bytes, and returns the view of them that holds
     * it. The view, and what's read from it, change when the bytes are
     * written again. Reusing bytes saves allocating and zeroing new ones,
     * which takes longest for large tables.
     *
     * @throws {RangeError} If `bytes` are shorter than the table, before
     * any of them is written.
     */
    static serializeInto(fields: TrackFields, bytes: Uint8Array): Uint8Array {
        const sizer = new TableSizer(5, Track.#LAYOUT);
        sizer.addUint32();
        sizer.addStruct(Vec2.SIZE);
        sizer.addTable(Frame.ALIGNMENT);
        Frame.size(sizer, fields.frame);
        sizer.addFloat32Array(fields.points.length);
        sizer.addString(fields.name);

        const writer = sizer.writer(bytes);
        writer.setUint32(0, fields.id);
        writer.setStruct(1, Vec2.serialize(fields.origin));
        writer.setTable(2, Frame.ALIGNMENT);
        Frame.write(writer, fields.frame);
        writer.setFloat32Array(3, fields.points);
        writer.setString(4, fields.name);

        return writer.bytes();
    }

    id(): number {
        return this.#buffer.getUint32(this.#buffer.rootOffset(0));
    }

    origin(): Vec2 {
        return new Vec2(this.#buffer.bytes(), this.#buffer.rootOffset(1));
    }

    frame(): Frame {
        return new Frame(this.#buffer, this.#buffer.rootOffset(2));
    }

    points(): Float32Array {
        return this.#buffer.getFloat32Array(this.#buffer.rootOffset(3));
    }

    name(): string {
        return this.#buffer.getString(this.#buffer.rootOffset(4));
    }

    /**
     * Reads every field into the `TrackFields` that writes it, nested
     * tables and the items of vectors and arrays of structs included
     */
    fields(): TrackFields {
        return {
            id: this.#buffer.getUint32(this.#buffer.rootOffset(0)),
            origin: Vec2.read(this.#buffer.bytes(), this.#buffer.rootOffset(1)),
            frame: Frame.read(this.#buffer, this.#buffer.rootOffset(2)),
            points: this.#buffer.getFloat32Array(this.#buffer.rootOffset(3)),
            name: this.#buffer.getString(this.#buffer.rootOffset(4))
        };
    }
}

/** The fields of a `Track`, to write */
export interface TrackFields {
    id: number;
    origin: Vec2Fields;
    frame: FrameFields;
    points: ArrayLike<number> | Float32Array;
    name: string;
}

